package com.leo2agust.labs;
import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;import org.json.*;
public class LabsLogWidget extends AppWidgetProvider{
 @Override public void onEnabled(Context c){WidgetHttp.scheduleAutoRefresh(c);}@Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if("com.leo2agust.labs.REFRESH_WIDGET".equals(i.getAction())){int id=i.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);if(id!=AppWidgetManager.INVALID_APPWIDGET_ID)update(c,AppWidgetManager.getInstance(c),id);}}@Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){WidgetHttp.scheduleAutoRefresh(c);for(int id:ids)update(c,m,id);}
 static void update(final Context c,final AppWidgetManager m,final int id){RemoteViews v=views(c,"Mengambil aktivitas…","","","LIVE");bind(c,v,id);m.updateAppWidget(id,v);new Thread(new Runnable(){public void run(){updateSync(c,m,id);}}).start();}
 static void updateSync(Context c,AppWidgetManager m,int id){String a="—",b="—",d="—",badge="LOGS";try{JSONObject data=WidgetHttp.get(c,"/api/lab/activity?limit=3");JSONArray e=data.optJSONArray("events");badge=data.optInt("active_sessions",0)+" ACTIVE";if(e!=null&&e.length()>0)a=sum(e.optJSONObject(0));if(e!=null&&e.length()>1)b=sum(e.optJSONObject(1));if(e!=null&&e.length()>2)d=sum(e.optJSONObject(2));}catch(Exception e){a=WidgetHttp.errorText(e);b="Tap widget untuk membuka Labs";d="";badge="PAUSED";}RemoteViews v=views(c,a,b,d,badge);bind(c,v,id);m.updateAppWidget(id,v);}private static String sum(JSONObject e){if(e==null)return"—";String p=e.optString("phase","event").toUpperCase(),t=e.optString("summary","Aktivitas Labs");if(t.length()>54)t=t.substring(0,51)+"…";return WidgetHttp.eventTime(e)+" · "+p+" · "+t;}private static RemoteViews views(Context c,String a,String b,String d,String badge){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_log);v.setTextViewText(R.id.wl_title,WidgetHttp.brand(c)+" · Process Logs");v.setTextViewText(R.id.wl_badge,badge);v.setTextViewText(R.id.wl_line1,a);v.setTextViewText(R.id.wl_line2,b);v.setTextViewText(R.id.wl_line3,d);return v;}private static void bind(Context c,RemoteViews v,int id){v.setOnClickPendingIntent(R.id.wl_root,WidgetHttp.openPage(c,"activity",22));v.setOnClickPendingIntent(R.id.wl_refresh,WidgetHttp.refresh(c,LabsLogWidget.class,id,2200));}}
